import React, { useState, useRef, useId, useCallback } from 'react';
import { motion, AnimatePresence, useReducedMotion } from 'framer-motion';
import type { HTMLMotionProps } from 'framer-motion';
import {
  Home,
  FolderKanban,
  MessageSquare,
  BarChart3,
  Calendar,
  Star,
  MoreVertical,
  PanelLeftClose,
  PanelLeft,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { cn } from '../../lib/utils';
import { motionTransitions } from '../../lib/motion-tokens';

export interface SidebarItem {
  id: string;
  label: string;
  icon?: LucideIcon | React.ComponentType<{ className?: string; size?: number | string }>;
  badge?: string | number | { text: string; variant?: 'default' | 'accent' | 'dot' };
  disabled?: boolean;
  href?: string;
  onClick?: () => void;
  tooltip?: string;
}

export interface SidebarUser {
  name: string;
  email?: string;
  status?: string;
  avatar?: string;
  onMenuClick?: () => void;
}

export interface SidebarBrand {
  name: string;
  logo?: React.ReactNode;
  badge?: string;
}

export interface SidebarProps extends Omit<HTMLMotionProps<'aside'>, 'onChange'> {
  items?: SidebarItem[];
  activeId?: string;
  defaultActiveId?: string;
  onChange?: (id: string, item: SidebarItem) => void;
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  collapsible?: boolean;
  theme?: 'dark' | 'light' | 'auto';
  brand?: SidebarBrand;
  user?: SidebarUser;
  footerSlot?: React.ReactNode;
  className?: string;
}

const defaultItems: SidebarItem[] = [
  { id: 'home', label: 'Home', icon: Home },
  { id: 'projects', label: 'Projects', icon: FolderKanban, badge: '12' },
  { id: 'chat', label: 'Chat', icon: MessageSquare, badge: { text: 'New', variant: 'accent' } },
  { id: 'analytics', label: 'Analytics', icon: BarChart3 },
  { id: 'calendar', label: 'Calendar', icon: Calendar },
  { id: 'favorites', label: 'Favorites', icon: Star },
];

/**
 * EasyUI Signature Abstract Logo Mark
 */
const EasyUILogoMark: React.FC<{ className?: string }> = ({ className }) => (
  <div
    className={cn(
      'relative flex items-center justify-center w-8 h-8 rounded-lg overflow-hidden select-none',
      'bg-gradient-to-br from-zinc-800 to-zinc-950 border border-white/10 shadow-[0_0_15px_rgba(168,85,247,0.15)]',
      className
    )}
  >
    <div className="absolute inset-0 bg-gradient-to-tr from-violet-500/20 via-transparent to-sky-400/20" />
    <svg
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className="w-4 h-4 text-white relative z-10"
      aria-hidden="true"
    >
      <rect x="4" y="4" width="7" height="7" rx="2" fill="currentColor" fillOpacity="0.9" />
      <rect x="13" y="4" width="7" height="7" rx="2" fill="currentColor" fillOpacity="0.4" />
      <rect x="4" y="13" width="7" height="7" rx="2" fill="currentColor" fillOpacity="0.4" />
      <rect x="13" y="13" width="7" height="7" rx="2" fill="url(#easyui-grad)" />
      <defs>
        <linearGradient id="easyui-grad" x1="13" y1="13" x2="20" y2="20" gradientUnits="userSpaceOnUse">
          <stop stopColor="#A855F7" />
          <stop offset="1" stopColor="#38BDF8" />
        </linearGradient>
      </defs>
    </svg>
  </div>
);

export const Sidebar: React.FC<SidebarProps> = ({
  items = defaultItems,
  activeId: controlledActiveId,
  defaultActiveId,
  onChange,
  collapsed: controlledCollapsed,
  defaultCollapsed = false,
  onCollapsedChange,
  collapsible = true,
  theme = 'dark',
  brand = { name: 'EasyUI', badge: 'v2.4' },
  user = {
    name: 'Alex Rivera',
    status: 'Pro Plan',
    email: 'alex@easyui.dev',
  },
  footerSlot,
  className,
  ...props
}) => {
  const [uncontrolledActiveId, setUncontrolledActiveId] = useState(
    defaultActiveId || items[0]?.id || 'home'
  );
  const activeId = controlledActiveId !== undefined ? controlledActiveId : uncontrolledActiveId;

  const [uncontrolledCollapsed, setUncontrolledCollapsed] = useState(defaultCollapsed);
  const isCollapsed = controlledCollapsed !== undefined ? controlledCollapsed : uncontrolledCollapsed;

  const [hoveredItemId, setHoveredItemId] = useState<string | null>(null);
  const [orbitTick, setOrbitTick] = useState(0);
  const layoutInstanceId = useId();
  const prefersReduced = useReducedMotion();
  const navRef = useRef<HTMLUListElement>(null);

  const isDark = theme === 'dark' || theme === 'auto';

  const setCollapsed = useCallback(
    (nextVal: boolean) => {
      if (controlledCollapsed === undefined) {
        setUncontrolledCollapsed(nextVal);
      }
      onCollapsedChange?.(nextVal);
    },
    [controlledCollapsed, onCollapsedChange]
  );

  const handleItemSelect = useCallback(
    (item: SidebarItem) => {
      if (item.disabled) return;
      if (controlledActiveId === undefined) {
        setUncontrolledActiveId(item.id);
      }
      // Re-trigger the energy orbit flourish
      setOrbitTick((prev) => prev + 1);
      onChange?.(item.id, item);
      item.onClick?.();
    },
    [controlledActiveId, onChange]
  );

  // Keyboard navigation across sidebar items
  const handleKeyDown = (e: React.KeyboardEvent<HTMLUListElement>) => {
    const enabledItems = items.filter((it) => !it.disabled);
    if (!enabledItems.length) return;

    const currentIndex = enabledItems.findIndex((it) => it.id === activeId);

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      const nextIndex = (currentIndex + 1) % enabledItems.length;
      handleItemSelect(enabledItems[nextIndex]);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      const prevIndex = (currentIndex - 1 + enabledItems.length) % enabledItems.length;
      handleItemSelect(enabledItems[prevIndex]);
    } else if (e.key === 'Home') {
      e.preventDefault();
      handleItemSelect(enabledItems[0]);
    } else if (e.key === 'End') {
      e.preventDefault();
      handleItemSelect(enabledItems[enabledItems.length - 1]);
    }
  };

  return (
    <motion.aside
      initial={false}
      animate={{
        width: isCollapsed ? 68 : 252,
      }}
      transition={prefersReduced ? { duration: 0 } : motionTransitions.springSnappy}
      role="navigation"
      aria-label="Main Sidebar"
      className={cn(
        'relative flex flex-col h-full select-none shrink-0 z-30 font-sans',
        'border-r transition-colors duration-300',
        isDark
          ? 'bg-[#0B0B0E]/95 text-[#F5F5F5] border-[#1E1E24]/80 shadow-[1px_0_24px_rgba(0,0,0,0.4)] backdrop-blur-xl'
          : 'bg-[#FCFCFD]/95 text-[#18181B] border-zinc-200/80 shadow-[1px_0_20px_rgba(0,0,0,0.03)] backdrop-blur-xl',
        className
      )}
      {...props}
    >
      {/* Background delicate atmospheric ambient glow */}
      <div
        aria-hidden="true"
        className={cn(
          'pointer-events-none absolute -top-16 -left-16 w-56 h-56 rounded-full blur-[70px] transition-opacity duration-500',
          isDark
            ? 'bg-gradient-to-br from-violet-600/10 via-fuchsia-600/5 to-sky-500/10 opacity-70'
            : 'bg-gradient-to-br from-violet-500/5 via-fuchsia-500/5 to-sky-400/5 opacity-50'
        )}
      />

      {/* Top Header / Brand Logo */}
      <div className="relative flex items-center justify-between px-3.5 py-4 min-h-[64px]">
        <div className="flex items-center gap-2.5 overflow-hidden">
          {brand.logo || <EasyUILogoMark />}

          <AnimatePresence initial={false}>
            {!isCollapsed && (
              <motion.div
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -8 }}
                transition={prefersReduced ? { duration: 0 } : motionTransitions.easeFast}
                className="flex items-center gap-2 overflow-hidden whitespace-nowrap"
              >
                <span
                  className={cn(
                    'text-sm font-semibold tracking-tight',
                    isDark ? 'text-[#F5F5F5]' : 'text-zinc-900'
                  )}
                >
                  {brand.name}
                </span>
                {brand.badge && (
                  <span
                    className={cn(
                      'text-[10px] font-mono px-1.5 py-0.5 rounded font-medium leading-none tracking-wider',
                      isDark
                        ? 'bg-white/[0.06] text-[#A3A3A3] border border-white/[0.08]'
                        : 'bg-zinc-100 text-zinc-600 border border-zinc-200'
                    )}
                  >
                    {brand.badge}
                  </span>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {collapsible && !isCollapsed && (
          <button
            type="button"
            onClick={() => setCollapsed(true)}
            aria-label="Collapse sidebar"
            className={cn(
              'p-1.5 rounded-lg transition-colors duration-150',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/50',
              isDark
                ? 'text-[#737373] hover:text-[#F5F5F5] hover:bg-white/[0.06]'
                : 'text-zinc-400 hover:text-zinc-900 hover:bg-zinc-100'
            )}
          >
            <PanelLeftClose className="w-4 h-4" />
          </button>
        )}

        {collapsible && isCollapsed && (
          <button
            type="button"
            onClick={() => setCollapsed(false)}
            aria-label="Expand sidebar"
            className={cn(
              'absolute inset-0 w-full h-full opacity-0 hover:opacity-100 flex items-center justify-center',
              'transition-opacity duration-200 bg-black/40 backdrop-blur-xs rounded-t-lg',
              'focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/50'
            )}
          >
            <PanelLeft className="w-4 h-4 text-white" />
          </button>
        )}
      </div>

      {/* Navigation List */}
      <div className="flex-1 overflow-y-auto px-2.5 py-2 space-y-1 scrollbar-none">
        <ul
          ref={navRef}
          role="tablist"
          aria-orientation="vertical"
          onKeyDown={handleKeyDown}
          className="space-y-1"
        >
          {items.map((item) => {
            const isActive = activeId === item.id;
            const Icon = item.icon;

            return (
              <li
                key={item.id}
                role="presentation"
                className="relative"
                onMouseEnter={() => setHoveredItemId(item.id)}
                onMouseLeave={() => setHoveredItemId(null)}
              >
                <button
                  type="button"
                  role="tab"
                  id={`sidebar-item-${item.id}`}
                  aria-selected={isActive}
                  aria-disabled={item.disabled}
                  disabled={item.disabled}
                  onClick={() => handleItemSelect(item)}
                  className={cn(
                    'group relative flex items-center w-full rounded-xl transition-all duration-200 select-none text-left',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/50',
                    isCollapsed ? 'justify-center p-2.5 h-10' : 'px-3 py-2.5 gap-3 h-10',
                    item.disabled && 'opacity-30 cursor-not-allowed pointer-events-none',
                    !isActive && !item.disabled && (
                      isDark
                        ? 'text-[#8A8A8A] hover:text-[#F5F5F5] hover:bg-white/[0.03]'
                        : 'text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100/70'
                    )
                  )}
                >
                  {/* Active Soft Floating Pill with continuous layoutId */}
                  {isActive && (
                    <motion.div
                      layoutId={`sidebar-active-pill-${layoutInstanceId}`}
                      transition={prefersReduced ? { duration: 0 } : motionTransitions.springSnappy}
                      className={cn(
                        'absolute inset-0 rounded-xl pointer-events-none overflow-hidden',
                        isDark
                          ? 'bg-white/[0.06] border border-white/[0.12] shadow-[0_0_24px_-4px_rgba(168,85,247,0.18),0_0_12px_-2px_rgba(59,130,246,0.12)]'
                          : 'bg-black/[0.05] border border-black/[0.08] shadow-[0_0_20px_-4px_rgba(168,85,247,0.1),0_0_10px_-2px_rgba(59,130,246,0.08)]'
                      )}
                    >
                      {/* Subtle chromatic ambient background highlight */}
                      <div
                        className={cn(
                          'absolute inset-0 pointer-events-none opacity-60',
                          isDark
                            ? 'bg-gradient-to-r from-violet-500/10 via-fuchsia-500/5 to-sky-500/10'
                            : 'bg-gradient-to-r from-violet-500/5 via-fuchsia-500/3 to-sky-500/5'
                        )}
                      />

                      {/* Signature Interaction: Subtle Traveling Energy/Orbit Perimeter Beam */}
                      {!prefersReduced && (
                        <motion.div
                          key={`orbit-${orbitTick}`}
                          initial={{ opacity: 0, offsetDistance: '0%' }}
                          animate={{
                            opacity: [0, 1, 0.85, 0.4],
                            rotate: [0, 360],
                          }}
                          transition={{
                            opacity: { duration: 1.2, ease: 'easeOut' },
                            rotate: { duration: 6, repeat: Infinity, ease: 'linear' },
                          }}
                          className="absolute -inset-1 pointer-events-none overflow-hidden rounded-xl opacity-40"
                        >
                          <div
                            className={cn(
                              'absolute -top-1/2 -left-1/2 w-[200%] h-[200%]',
                              'bg-[conic-gradient(from_0deg_at_50%_50%,transparent_0deg,rgba(168,85,247,0.4)_50deg,rgba(56,189,248,0.4)_90deg,transparent_130deg)]'
                            )}
                          />
                        </motion.div>
                      )}

                      {/* Inner hairline glass reflection */}
                      <div className="absolute inset-x-0 top-0 h-[1px] bg-gradient-to-r from-transparent via-white/20 to-transparent" />
                    </motion.div>
                  )}

                  {/* Icon with subtle spring scale on active state */}
                  {Icon && (
                    <motion.div
                      animate={{
                        scale: isActive ? 1.05 : 1,
                      }}
                      transition={motionTransitions.springSnappy}
                      className={cn(
                        'relative z-10 flex items-center justify-center shrink-0 transition-colors duration-150',
                        isActive
                          ? (isDark ? 'text-white' : 'text-zinc-950')
                          : (isDark ? 'text-[#8A8A8A] group-hover:text-[#F5F5F5]' : 'text-zinc-500 group-hover:text-zinc-900')
                      )}
                    >
                      <Icon size={18} strokeWidth={isActive ? 2.2 : 2} />
                    </motion.div>
                  )}

                  {/* Label (when expanded) */}
                  <AnimatePresence initial={false}>
                    {!isCollapsed && (
                      <motion.span
                        initial={{ opacity: 0, width: 0 }}
                        animate={{ opacity: 1, width: 'auto' }}
                        exit={{ opacity: 0, width: 0 }}
                        transition={prefersReduced ? { duration: 0 } : motionTransitions.easeFast}
                        className={cn(
                          'relative z-10 text-xs font-medium truncate flex-1 tracking-normal transition-colors duration-150',
                          isActive
                            ? (isDark ? 'text-[#F5F5F5] font-semibold' : 'text-zinc-950 font-semibold')
                            : (isDark ? 'text-[#A3A3A3] group-hover:text-[#F5F5F5]' : 'text-zinc-600 group-hover:text-zinc-900')
                        )}
                      >
                        {item.label}
                      </motion.span>
                    )}
                  </AnimatePresence>

                  {/* Badge (when expanded) */}
                  <AnimatePresence initial={false}>
                    {!isCollapsed && item.badge && (
                      <motion.div
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.8 }}
                        transition={motionTransitions.springSnappy}
                        className="relative z-10 ml-auto shrink-0"
                      >
                        {typeof item.badge === 'object' && item.badge.variant === 'dot' ? (
                          <span className="flex h-2 w-2 rounded-full bg-violet-400 shadow-[0_0_8px_rgba(168,85,247,0.6)]" />
                        ) : typeof item.badge === 'object' && item.badge.variant === 'accent' ? (
                          <span
                            className={cn(
                              'text-[10px] font-mono px-1.5 py-0.5 rounded-full font-medium leading-none tracking-wider',
                              'bg-violet-500/15 text-violet-300 border border-violet-500/30'
                            )}
                          >
                            {item.badge.text}
                          </span>
                        ) : (
                          <span
                            className={cn(
                              'text-[10px] font-mono px-1.5 py-0.5 rounded-full font-medium leading-none tracking-wider',
                              isDark
                                ? 'bg-white/[0.06] text-[#A3A3A3] border border-white/[0.08]'
                                : 'bg-zinc-100 text-zinc-600 border border-zinc-200'
                            )}
                          >
                            {typeof item.badge === 'object' ? item.badge.text : item.badge}
                          </span>
                        )}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </button>

                {/* Collapsed Tooltip (accessible hover/focus state) */}
                {isCollapsed && hoveredItemId === item.id && (
                  <motion.div
                    initial={{ opacity: 0, x: -4, scale: 0.95 }}
                    animate={{ opacity: 1, x: 0, scale: 1 }}
                    exit={{ opacity: 0, x: -4, scale: 0.95 }}
                    transition={motionTransitions.springSnappy}
                    role="tooltip"
                    id={`tooltip-${item.id}`}
                    className={cn(
                      'absolute left-full ml-3 top-1/2 -translate-y-1/2 z-50 px-2.5 py-1.5 rounded-lg whitespace-nowrap shadow-xl pointer-events-none',
                      'flex items-center gap-2 border text-xs font-medium',
                      isDark
                        ? 'bg-[#151518] text-[#F5F5F5] border-white/10 shadow-[0_8px_20px_rgba(0,0,0,0.6)]'
                        : 'bg-white text-zinc-900 border-zinc-200 shadow-[0_8px_20px_rgba(0,0,0,0.1)]'
                    )}
                  >
                    <span>{item.label}</span>
                    {item.badge && (
                      <span
                        className={cn(
                          'text-[10px] font-mono px-1 py-0.2 rounded font-medium',
                          typeof item.badge === 'object' && item.badge.variant === 'accent'
                            ? 'bg-violet-500/20 text-violet-300'
                            : 'bg-white/10 text-zinc-400'
                        )}
                      >
                        {typeof item.badge === 'object' ? item.badge.text : item.badge}
                      </span>
                    )}
                  </motion.div>
                )}
              </li>
            );
          })}
        </ul>
      </div>

      {/* Optional Custom Footer Slot */}
      {footerSlot && (
        <div className="px-3 py-2 border-t border-white/[0.04]">
          {footerSlot}
        </div>
      )}

      {/* Bottom User Section */}
      {user && (
        <div
          className={cn(
            'relative mt-auto border-t transition-colors duration-200',
            isDark ? 'border-[#1E1E24]/80' : 'border-zinc-200/80',
            isCollapsed ? 'p-2 flex justify-center' : 'p-3'
          )}
        >
          <div
            className={cn(
              'group relative flex items-center rounded-xl transition-colors duration-150',
              isCollapsed ? 'justify-center w-10 h-10' : 'gap-2.5 p-1.5 w-full',
              isDark ? 'hover:bg-white/[0.04]' : 'hover:bg-zinc-100/70'
            )}
          >
            {/* Small circular gradient avatar */}
            <div className="relative shrink-0">
              {user.avatar ? (
                <img
                  src={user.avatar}
                  alt={user.name}
                  className="w-8 h-8 rounded-full object-cover ring-1 ring-white/10"
                />
              ) : (
                <div
                  className={cn(
                    'w-8 h-8 rounded-full flex items-center justify-center font-medium text-xs text-white select-none',
                    'bg-gradient-to-tr from-violet-600 via-indigo-500 to-sky-400 shadow-[0_0_12px_rgba(168,85,247,0.3)]',
                    'ring-1 ring-white/20'
                  )}
                >
                  {user.name.slice(0, 2).toUpperCase()}
                </div>
              )}
              {/* Online status indicator */}
              <span className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full bg-emerald-400 ring-2 ring-[#0B0B0E]" />
            </div>

            {/* Name and tiny status/subtitle */}
            <AnimatePresence initial={false}>
              {!isCollapsed && (
                <motion.div
                  initial={{ opacity: 0, width: 0 }}
                  animate={{ opacity: 1, width: 'auto' }}
                  exit={{ opacity: 0, width: 0 }}
                  transition={prefersReduced ? { duration: 0 } : motionTransitions.easeFast}
                  className="flex flex-col min-w-0 flex-1 overflow-hidden text-left"
                >
                  <span
                    className={cn(
                      'text-xs font-semibold truncate',
                      isDark ? 'text-[#F5F5F5]' : 'text-zinc-900'
                    )}
                  >
                    {user.name}
                  </span>
                  <span
                    className={cn(
                      'text-[10px] font-mono truncate',
                      isDark ? 'text-[#737373]' : 'text-zinc-500'
                    )}
                  >
                    {user.status || user.email || 'Online'}
                  </span>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Three-dot menu button */}
            {!isCollapsed && (
              <button
                type="button"
                onClick={user.onMenuClick}
                aria-label="User profile settings"
                className={cn(
                  'p-1.5 rounded-lg opacity-60 hover:opacity-100 transition-opacity duration-150',
                  'focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/50',
                  isDark ? 'text-[#A3A3A3] hover:text-white' : 'text-zinc-500 hover:text-zinc-900'
                )}
              >
                <MoreVertical className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        </div>
      )}
    </motion.aside>
  );
};
